    async function clickAgreementReq(value: any, quotationTenderType: any) {
     
        await WebUI.comment("DEBUG Agreement = [" + value + "]")
        await WebUI.comment("DEBUG QuotationTenderType = [" + quotationTenderType + "]")
     
        gAssert(value != null && value.toString().trim(), "Agreement value is empty")
        gAssert(quotationTenderType != null && quotationTenderType.toString().trim(), "QuotationTenderType is empty")
     
        let intValue: any = value.toString().trim().toInteger()
        let tenderType: any = quotationTenderType.toString().trim().toInteger()
     
        gAssert([1, 2].includes(intValue), "Invalid Agreement: " + intValue )
        gAssert(tenderType >= 1, "Invalid QuotationTenderType: " + tenderType)
     
        let baseId: any = "_scCreateManualSourcing_WAR_NGePportlet_:form:"
     
        // =====================================
        // TYPE 1-6: RADIO BUTTON
        // =====================================
     
        if (tenderType <= 6) {
     
            await WebUI.comment("Required Agreement: Radio Button")
            let radioIndex: any = (intValue == 1) ? "0" : "1" 
            let radio: any = new TestObject("agreementReq_radio") 
            radio.addProperty("xpath", ConditionType.EQUALS,
                "//*[@id='" + baseId + "agreementReq:" + radioIndex +
                "']/ancestor::div[contains(@class,'ui-radiobutton')]" +
                "/div[contains(@class,'ui-radiobutton-box')]"
            )
     
            await WebUI.waitForElementClickable(radio, 20)
            await WebUI.click(radio)
     
        } else {
     
            // =====================================
            // TYPE 7+: DROPDOWN
            // =====================================
     
            await WebUI.comment("Required Agreement: Dropdown")
            let dd: any = new TestObject("agreementReq_dropdown")
            dd.addProperty("xpath", ConditionType.EQUALS,
                "//*[@id='" + baseId +
                "agreementReqPk7Per']/div[3]/span"
            )
     
            await WebUI.waitForElementClickable(dd, 20)
            await WebUI.click(dd)
     
            let optXpath: any = (intValue == 1)
                ? "//*[@id='" + baseId +
                  "agreementReqPk7Per_panel']//li[2]"
                : "//*[@id='" + baseId +
                  "agreementReqPk7Per_panel']//li[3]"
     
            let opt: any = new TestObject("agreementReq_option")
     
            opt.addProperty(
                "xpath",
                ConditionType.EQUALS,
                optXpath
            )
     
            await WebUI.waitForElementClickable(opt, 20)
            await WebUI.click(opt)
        }
     
        // =====================================
        // AGREEMENT = NO
        // =====================================
     
        if (intValue == 2) {
            await WebUI.comment("Agreement No: Checking UI condition")
     
            // CONDITION 1: CONFIRMATION POPUP
            let popYes: any = new TestObject("popYes")
            popYes.addProperty("xpath", ConditionType.EQUALS,
                "//div[contains(@class,'ui-dialog') " +
                "and not(contains(@class,'ui-overlay-hidden'))]" +
                "//button[contains(@onclick,'qtChangeAgreementReqDlg.hide') " +
                "and contains(@onclick,'agreementReqPG') " +
                "and .//span[normalize-space()='Yes']]"
            )
     
            // CONDITION 2: UPLOAD APPROVAL LETTER ICON
            let uploadIcon: any = new TestObject(
                "uploadApprovalLetterIcon"
            )
            uploadIcon.addProperty("xpath", ConditionType.EQUALS,
                "//button[contains(@onclick,'uploadApprovalLetterDlg.show()') " +
                "and .//span[contains(@class,'ui-icon-upload')]]"
            )
     
            // Check popup first
            let popupVisible: any = await WebUI.waitForElementVisible(
                popYes, 5, FailureHandling.OPTIONAL
            )
     
            if (popupVisible) {
     
                // =====================================
                // CONDITION 1: CLICK POPUP YES
                // =====================================
                await WebUI.comment(
                    "Condition 1: Confirmation popup detected"
                )
     
                await WebUI.waitForElementClickable(popYes, 20)
                let el: any = await WebUI.findWebElement(popYes, 20)
     
                await WebUI.executeJavaScript(
                    "arguments[0].click();",
                    Arrays.asList(el)
                )
     
                await WebUI.comment("SUCCESS: Popup Yes clicked")
     
            } else {
     
                // =====================================
                // CONDITION 2: UPLOAD DOCUMENT
                // =====================================
     
                await WebUI.comment(
                    "Checking Upload Approval Letter icon"
                )
                let uploadAvailable: any = await WebUI.waitForElementClickable(
                    uploadIcon, 15, FailureHandling.OPTIONAL
                )
                if (!uploadAvailable) {
                    await WebUI.takeScreenshot()
                    gAssert(false, "Agreement No: Neither popup nor upload icon available")
                }
     
                // STEP 1: CLICK UPLOAD ICON
     
                await WebUI.comment("Clicking Upload Approval Letter icon")
                await WebUI.click(uploadIcon)
     
                // STEP 2: WAIT FOR UPLOAD DIALOG
     
                let uploadDialog: any = new TestObject(
                    "uploadApprovalLetterDialog"
                )
     
                uploadDialog.addProperty("xpath", ConditionType.EQUALS,
                    "//div[contains(@id,'uploadApprovalLetterDlg') " +
                    "and contains(@class,'ui-dialog') " +
                    "and not(contains(@class,'ui-overlay-hidden'))]"
                )
     
                await WebUI.waitForElementVisible(uploadDialog, 20)
                await WebUI.comment("Upload Approval Letter dialog opened")
     
                // STEP 3: PDF FILE PATH
     
                let agreementApprovalPdfPath: any =
                    System.getProperty("user.dir") +
                    "/TestData/UploadFiles/File_pdf_for_testing.pdf"
     
                gAssert(new File(agreementApprovalPdfPath).isFile(), "PDF file not found: " + agreementApprovalPdfPath) // STEP 4: CHOOSE FILE
     
                await up(
                    findTestObject(
                        'Object Repository/Direct LOA/1. Direct LOA Requistioner/LOA And Attachment Tab/Choose File'
                    ),
                    agreementApprovalPdfPath,
                    3
                )
     
                await WebUI.comment(
                    "PDF selected: " +
                    new File(agreementApprovalPdfPath).getName()
                )
     
                // =====================================
                // STEP 5: CLICK UPLOAD ARROW BUTTON
                // =====================================
     
                let btnUploadFile: any = new TestObject(
                    "btnUploadFile"
                )
     
                btnUploadFile.addProperty("xpath", ConditionType.EQUALS,
                    "//div[contains(@id,'uploadApprovalLetterDlg') " +
                    "and contains(@class,'ui-dialog') " +
                    "and not(contains(@class,'ui-overlay-hidden'))]" +
                    "//button[.//span[contains(@class,'ui-icon-arrowreturnthick-1-n')]]"
                )
     
                await WebUI.waitForElementClickable(btnUploadFile, 20)
                await WebUI.click(btnUploadFile)
                await WebUI.comment(
                    "Upload arrow button clicked for: " +
                    new File(agreementApprovalPdfPath).getName()
                )
     
                // Upload completion should be verified
                // using the application's success indicator.
            }
        }
     
        await WebUI.comment(
            "SUCCESS Required Agreement selection = " +
            (intValue == 1 ? "Yes" : "No")
        )
    }
     
    // =====================================
    // STEP 1: SELECT QUOTATION TENDER TYPE
    // =====================================
     
    await selectDropdownByIndex(
        findTestObject(
            'Object Repository/Direct LOA/1. Direct LOA Requistioner/General infomation Tab/Dropdown Quotation_Tender Type'
        ),
        QuotationTenderType
    )
     
    // =====================================
