    await WebUI.delay(0.5)
    await waitBlockUI(30)

    let userRow: any = findTestObject('Object Repository/Direct LOA/1. Direct LOA Requistioner/LOA And Attachment Tab/Click in user Table')
    await wVisible(userRow, 20)
    await WebUI.scrollToElement(userRow, 2)

